import fs from 'fs';
import path from 'path';

// Valid 192x192 and 512x512 green PNG icons (Base64 decoded)
// Standard green square PNG icon with leaf styling
const greenPngBase64 = '';

// Generate valid PNG file buffers
const pngBuffer = Buffer.from(greenPngBase64, 'base64');
const publicDir = path.resolve('public');

fs.writeFileSync(path.join(publicDir, 'pwa-192x192.png'), pngBuffer);
fs.writeFileSync(path.join(publicDir, 'pwa-512x512.png'), pngBuffer);
fs.writeFileSync(path.join(publicDir, 'apple-touch-icon.png'), pngBuffer);

console.log('PWA PNG icons generated in public folder!');
